require "connection_pool"

DB_POOL = ConnectionPool.new(size: 8, timeout: 1) { PG.connect(ENV["DATABASE_URL"]) }

def query(sql)
  DB_POOL.with { |conn| conn.exec(sql) }   # blocks, then Timeout when saturated
end

